import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Linux 上重命名一组文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上重命名一组文件 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上重命名一组文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上重命名一组文件 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190826 How to rename a group of files on Linux","title":"如何在 Linux 上重命名一组文件","tag":"201909","desc":""},"relativePath":"201909/20190826 How to rename a group of files on Linux.md","filePath":"[post].md"}'),c={name:"201909/20190826 How to rename a group of files on Linux.md"};function h(g,s,u,m,k,b){const a=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上重命名一组文件" tabindex="-1">如何在 Linux 上重命名一组文件 <a class="header-anchor" href="#如何在-linux-上重命名一组文件" aria-label="Permalink to “如何在 Linux 上重命名一组文件”">​</a></h1><blockquote><p>要用单个命令重命名一组文件，请使用 rename 命令。它需要使用正则表达式，并且可以在开始前告诉你会有什么更改。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201909/03/005333hfm8yf90m2gm800g.jpg" alt=""></p><p>几十年来，Linux 用户一直使用 <code>mv</code> 命令重命名文件。它很简单，并且能做到你要做的。但有时你需要重命名一大组文件。在这种情况下，<code>rename</code> 命令可以使这个任务更容易。它只需要一些正则表达式的技巧。</p><p>与 <code>mv</code> 命令不同，<code>rename</code> 不允许你简单地指定旧名称和新名称。相反，它使用类似于 Perl 中的正则表达式。在下面的例子中，<code>s</code> 指定我们将第一个字符串替换为第二个字符串（旧的），从而将 <code>this.new</code> 变为 <code>this.old</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename &#39;s/new/old/&#39; this.new</span></span>
<span class="line"><span>$ ls this*</span></span>
<span class="line"><span>this.old</span></span></code></pre></div><p>使用 <code>mv this.new this.old</code> 可以更容易地进行更改一个，但是将字符串 <code>this</code> 变成通配符 <code>*</code>，你可以用一条命令将所有的 <code>*.new</code> 文件重命名为 <code>*.old</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.new</span></span>
<span class="line"><span>report.new  schedule.new  stats.new  this.new</span></span>
<span class="line"><span>$ rename &#39;s/new/old/&#39; *.new</span></span>
<span class="line"><span>$ ls *.old</span></span>
<span class="line"><span>report.old  schedule.old  stats.old  this.old</span></span></code></pre></div><p>正如你所料，<code>rename</code> 命令不限于更改文件扩展名。如果你需要将名为 <code>report.*</code> 的文件更改为 <code>review.*</code>，那么可以使用以下命令做到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename &#39;s/report/review/&#39; *</span></span></code></pre></div><p>正则表达式中的字符串可以更改文件名的任何部分，无论是文件名还是扩展名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename &#39;s/123/124/&#39; *</span></span>
<span class="line"><span>$ ls *124*</span></span>
<span class="line"><span>status.124  report124.txt</span></span></code></pre></div><p>如果你在 <code>rename</code> 命令中添加 <code>-v</code> 选项，那么该命令将提供一些反馈，以便你可以看到所做的更改，或许会包含你没注意的。这让你注意到并按需还原更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -v &#39;s/123/124/&#39; *</span></span>
<span class="line"><span>status.123 renamed as status.124</span></span>
<span class="line"><span>report123.txt renamed as report124.txt</span></span></code></pre></div><p>另一方面，使用 <code>-n</code>（或 <code>--nono</code>）选项会使 <code>rename</code> 命令告诉你将要做的但不会实际做的更改。这可以让你免于执行不不想要的操作，然后再还原更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;s/old/save/&#39; *</span></span>
<span class="line"><span>rename(logger.man-old, logger.man-save)</span></span>
<span class="line"><span>rename(lyrics.txt-old, lyrics.txt-save)</span></span>
<span class="line"><span>rename(olderfile-, saveerfile-)</span></span>
<span class="line"><span>rename(oldfile, savefile)</span></span>
<span class="line"><span>rename(review.old, review.save)</span></span>
<span class="line"><span>rename(schedule.old, schedule.save)</span></span>
<span class="line"><span>rename(stats.old, stats.save)</span></span>
<span class="line"><span>rename(this.old, this.save)</span></span></code></pre></div><p>如果你对这些更改满意，那么就可以运行不带 <code>-n</code> 选项的命令来更改文件名。</p><p>但请注意，正则表达式中的 <code>.</code> <strong>不会</strong>被视为句点，而是作为匹配任何字符的通配符。上面和下面的示例中的一些更改可能不是输入命令的人希望的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;s/.old/.save/&#39; *</span></span>
<span class="line"><span>rename(logger.man-old, logger.man.save)</span></span>
<span class="line"><span>rename(lyrics.txt-old, lyrics.txt.save)</span></span>
<span class="line"><span>rename(review.old, review.save)</span></span>
<span class="line"><span>rename(schedule.old, schedule.save)</span></span>
<span class="line"><span>rename(stats.old, stats.save)</span></span>
<span class="line"><span>rename(this.old, this.save)</span></span></code></pre></div><p>为确保句点按照字面意思执行，请在它的前面加一个反斜杠。这将使其不被解释为通配符并匹配任何字符。请注意，进行此更改时，仅选择了 <code>.old</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;s/\\.old/.save/&#39; *</span></span>
<span class="line"><span>rename(review.old, review.save)</span></span>
<span class="line"><span>rename(schedule.old, schedule.save)</span></span>
<span class="line"><span>rename(stats.old, stats.save)</span></span>
<span class="line"><span>rename(this.old, this.save)</span></span></code></pre></div><p>下面的命令会将文件名中的所有大写字母更改为小写，除了使用 <code>-n</code> 选项来确保我们在命令执行之前检查将做的修改。注意在正则表达式中使用了 <code>y</code>，这是改变大小写所必需的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;y/A-Z/a-z/&#39; W*</span></span>
<span class="line"><span>rename(WARNING_SIGN.pdf, warning_sign.pdf)</span></span>
<span class="line"><span>rename(Will_Gardner_buttons.pdf, will_gardner_buttons.pdf)</span></span>
<span class="line"><span>rename(Wingding_Invites.pdf, wingding_invites.pdf)</span></span>
<span class="line"><span>rename(WOW-buttons.pdf, wow-buttons.pdf)</span></span></code></pre></div><p>在上面的例子中，我们将所有大写字母更改为了小写，但这仅对以大写字母 <code>W</code> 开头的文件名。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>当你需要重命名大量文件时，<code>rename</code> 命令非常有用。请注意不要做比预期更多的更改。请记住，<code>-n</code>（或者 <code>--nono</code>）选项可以帮助你避免耗时的错误。</p><hr>`,27)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://www.networkworld.com/article/3433865/how-to-rename-a-group-of-files-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3433865/how-to-rename-a-group-of-files-on-linux.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const x=l(c,[["render",h]]);export{w as __pageData,x as default};
